def __find_staff_directory_window() -> bool:
    """Searches for the main Staff Directory window. Returns True if successfully located.

    -> Hidden function that should not be used outside the context of the staff_interops.py file context!

    :return: True or False
    :rtype: bool
    """
    return True if CommonActions.wait_for_object_exists(MosaiqCoreObjects.staff_Directory_Window) is not None else False

@deco.set_separate_app_context(MOSAIQ_APP_NAME)
def open_add_new_staff() -> None:
    """Locates the Location Directory main window > clicks the Add button
    waits for the Staff window to appear.
    """
    if __find_staff_directory_window():
        CommonActions.left_click_object(MosaiqCoreObjects.staff_Directory_add_Button)

@deco.set_separate_app_context(MOSAIQ_APP_NAME)
def open_change_staff() -> None:
    """Locates the Location Directory main window > clicks the Change button
    waits for the Staff window to appear.
    """
    if __find_staff_directory_window():
        CommonActions.left_click_object(MosaiqCoreObjects.staff_Directory_change_Button)

@deco.set_separate_app_context(MOSAIQ_APP_NAME)
def close_staff_directories() -> None:
    """Locates the Staff Directory window > clicks the Close button.
    """
    if __find_staff_directory_window():
        CommonActions.left_click_object(MosaiqCoreObjects.staff_Directory_close_Button)

@deco.set_separate_app_context(MOSAIQ_APP_NAME)
def delete_staff_directories(confirmed: bool) -> None:
    """Locates the Staff Directory  window > clicks the Delete button.
    """
    if __find_staff_directory_window():
        CommonActions.left_click_object(MosaiqCoreObjects.staff_Directory_delete_Button)
    if CommonActions.find_object(MosaiqCoreObjects.staff_Directory_warning_Window) is not None:
        CommonActions.left_click_object(MosaiqCoreObjects.oK_Button)
        if CommonActions.find_object(StaffObjects.staff_Window) is not None:
            if confirmed:
                CommonActions.left_click_object(StaffObjects.oK_Button)
            else:
                CommonActions.left_click_object(StaffObjects.cancel_Button)

@deco.set_separate_app_context(MOSAIQ_APP_NAME)
def change_staff_directories() -> None:
    """Locates the Staff Directory main window > clicks the change button.
    """
    if __find_staff_directory_window():
        CommonActions.left_click_object(MosaiqCoreObjects.staff_Directory_change_Button)
        CommonActions.find_object(StaffObjects.staff_Window)

@deco.set_separate_app_context(MOSAIQ_APP_NAME)
def select_staff_by_name(last_name, first_name, check_existence = False):
    if __find_staff_directory_window():
        CommonActions.press_key_sequence(last_name + "," + first_name)
        if check_existence:
            CommonActions.left_click_object(MosaiqCoreObjects.staff_Directory_change_Button)
            staff, _ = collect_staff_info()
            if staff.last_name != last_name or staff.first_name != first_name:
                raise NameError("the staff is not found")


def fill_staff_info(staff: Staff):
    staff_ops = StaffOps()
    staff_ops.last_name = staff.last_name
    staff_ops.first_name = staff.first_name
    staff_ops.mdl_initial = staff.mdl_initials
    staff_ops.initials = staff.initials
    staff_ops.suffix = staff.suffix
    staff_ops.alt_last_name = staff.alt_last_name
    staff_ops.alt_first_name = staff.alt_first_name
    staff_ops.alt_mdl_initial = staff.alt_mdl_initial

    staff_ops.user_name = staff.user_name
    staff_ops.clinical_id = staff.clinical_id
    staff_ops.department = staff.department
    staff_ops.type = staff.type
    staff_ops.active = staff.active
    staff_ops.category = staff.category
    staff_ops.accepts_assignment = staff.accepts_assignment
    staff_ops.code = staff.code
    staff_ops.non_physician = staff.non_physician
    staff_ops.page = staff.page
    staff_ops.ext_1 = staff.ext_1
    staff_ops.work = staff.work
    staff_ops.ext_2 = staff.ext_2
    staff_ops.fax = staff.fax
    staff_ops.email = staff.email
    staff_ops.direct_email = staff.direct_email

    #schedule
    staff_ops.duration = staff.duration
    staff_ops.schedulable = staff.schedulable
    staff_ops.code_capture = staff.code_capture

    #creditials
    staff_ops.billing = staff.billing
    staff_ops.other = staff.other

    #user resolution based UI settings
    staff_ops.resolution_based_ui_setting = staff.resolution_based_ui_setting

    #identification
    staff_ops.upin = staff.upin
    staff_ops.ssn = staff.ssn
    staff_ops.license = staff.license
    staff_ops.npi = staff.npi

    #personal
    staff_ops.address_1 = staff.address_1
    staff_ops.address_2 = staff.address_2
    staff_ops.city = staff.city
    staff_ops.state = staff.state
    staff_ops.postal = staff.postal
    staff_ops.phone = staff.phone
    staff_ops.ext = staff.ext
    staff_ops.gender = staff.gender
    staff_ops.dob = staff.dob

    staff_ops.click_button("OK")


def collect_staff_info():
    staff_ops = StaffOps()
    staff = Staff()
    staff.last_name = staff_ops.last_name
    staff.first_name = staff_ops.first_name
    staff.mdl_initials = staff_ops.mdl_initial
    staff.initials = staff_ops.initials
    staff.suffix = staff_ops.suffix
    staff.alt_last_name = staff_ops.alt_last_name
    staff.alt_first_name = staff_ops.alt_first_name
    staff.alt_mdl_initial = staff_ops.alt_mdl_initial

    staff.user_name = staff_ops.user_name
    staff.clinical_id = staff_ops.clinical_id
    staff.department = staff_ops.department
    staff.type = staff_ops.type
    staff.active = staff_ops.active
    staff.category = staff_ops.category
    staff.accepts_assignment = staff_ops.accepts_assignment
    staff.code = staff_ops.code
    staff.non_physician = staff_ops.non_physician
    staff.page = staff_ops.page
    staff.ext_1 = staff_ops.ext_1
    staff.work = staff_ops.work
    staff.ext_2 = staff_ops.ext_2
    staff.fax = staff_ops.fax
    staff.email = staff_ops.email
    staff.direct_email = staff_ops.direct_email

    #schedule
    staff.duration = staff_ops.duration
    staff.schedulable = staff_ops.schedulable
    staff.code_capture = staff_ops.code_capture

    #creditials
    staff.billing = staff_ops.billing
    staff.other = staff_ops.other

    #user resolution based UI settings
    staff.resolution_based_ui_setting = staff_ops.resolution_based_ui_setting

    #identification
    staff.upin = staff_ops.upin
    staff.ssn = staff_ops.ssn
    staff.license = staff_ops.license
    staff.npi = staff_ops.npi

    #personal
    staff.address_1 = staff_ops.address_1
    staff.address_2 = staff_ops.address_2
    staff.city = staff_ops.city
    staff.state = staff_ops.state
    staff.postal = staff_ops.postal
    staff.phone = staff_ops.phone
    staff.ext = staff_ops.ext
    staff.gender = staff_ops.gender
    staff.dob = staff_ops.dob

    return staff, staff_ops


