    @duration.setter
    def duration(self, value: str):
        org_duration = CommonActions.get_text(StaffObjects.duration_Edit)
        CommonActions.set_text(StaffObjects.duration_Edit, value)
        try:
            w = CommonActions.find_object({"text": "Input Duration Error"}, 200)
            if w:
                CommonActions.left_click_object({"text": "OK"})
                CommonActions.set_text(StaffObjects.duration_Edit, org_duration)
                self._duration = org_duration
                raise ValueError("Input Duration Error")
        except Exception:
            pass

